#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr;
    long n = strtol(argv[1], &endptr, 10);
    // Check conversion succeeded and consumed the whole argument
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (n < 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n > 30) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    // Compute Catalan numbers up to n (0‑based indexing)
    unsigned long long cat[31];
    cat[0] = 1ULL;
    for (int i = 1; i <= n; ++i) {
        unsigned long long sum = 0ULL;
        for (int j = 0; j < i; ++j) {
            sum += cat[j] * cat[i - 1 - j];
        }
        cat[i] = sum;
    }
    // The original program prints the n‑th Catalan number where n is 1‑based.
    // For n == 0 the behaviour is undefined, but the state machine never
    // reaches the computation for n == 0, so we simply print cat[n].
    printf("%llu\n", cat[n]);
    return 0;
}
